<template>
  <Layout>
    <WorkflowShell :flow-id="String(route.params.flowId)" :project-id="String(route.params.projectId)" :title="flow?.name || 'Release'" :subtitle="flow?.description || 'Build once, then ship everywhere.'" active="configuration">
      <template #actions><span v-if="flow" class="autosave-state"><i class="pi pi-check-circle" /> Saved automatically</span><Button label="Ship" icon="mdi mdi-rocket-launch-outline" :loading="running" :disabled="!flow || running" @click="ship" /></template>
      <main v-if="flow" class="release-page">
        <Message v-if="error" severity="error">{{ error }}</Message>
        <Message v-if="issues.length" severity="warn"><strong>{{ issueCount }} configuration issue{{ issueCount === 1 ? '' : 's' }}</strong><span class="summary-copy">Review the highlighted source, build, or deploy job before shipping.</span></Message>
        <section class="release-section"><div class="section-heading"><div><span class="eyebrow">Pipeline</span><h2>Source</h2><p>Choose the project or files this release represents.</p></div><Select v-model="sourcePicker" :options="catalog.sources" optionLabel="label" optionValue="id" placeholder="Change source" @change="changeSource" /></div><article class="source-card" :class="{ invalid: cardIssues('source').length }"><div class="provider-icon"><i :class="providerIcon(sourceDefinition?.icon, 'mdi mdi-source-branch')" /></div><div class="source-copy"><strong>{{ sourceDefinition?.label || flow.source.provider }}</strong><span>{{ sourcePath || 'No source selected' }}</span></div><Tag :value="cardIssues('source').length ? 'Needs attention' : sourcePath ? 'Ready' : 'Not configured'" :severity="cardIssues('source').length ? 'warn' : sourcePath ? 'success' : 'secondary'" /></article><div v-if="sourceDefinition?.fields?.length" class="settings-grid"><ReleaseFieldControl v-for="field in sourceDefinition.fields" :key="field.key" :field="field" :value="fieldValue(flow.source.config, field.key)" :options="fieldOptions(field)" :input-id="`source-${field.key}`" @update:value="setField(flow.source.config, field.key, $event)" /></div><Message v-if="cardIssues('source').length" severity="warn"><ul><li v-for="issue in cardIssues('source')" :key="issue.code + issue.path">{{ issue.message }}</li></ul></Message></section>
        <div class="pipeline-divider"><span>Build</span></div>
        <section class="release-section"><div class="section-heading"><div><span class="eyebrow">Jobs</span><h2>Build</h2><p>Build jobs create the artifacts that can be deployed below.</p></div><Select v-model="buildToAdd" :options="availableProducers" optionLabel="label" optionValue="id" placeholder="Add build job" @change="addBuild" /></div><div v-if="!flow.builds.length" class="empty-card"><i class="mdi mdi-hammer-wrench" /><strong>No build jobs yet</strong><span>Add a build provider to create release artifacts.</span></div><article v-for="(build, index) in flow.builds" :key="build.id" class="job-card" :class="{ disabled: !build.enabled, invalid: cardIssues(`builds.${index}`).length || (build.enabled && buildInputs(build).length === 0) }"><div class="job-header"><div class="provider-icon"><i :class="providerIcon(producerDefinition(build.engine)?.icon, 'mdi mdi-hammer-wrench')" /></div><div class="job-title"><strong>{{ build.name || producerDefinition(build.engine)?.label || build.engine }}</strong><span>{{ enabledTargetCount(build) }} target{{ enabledTargetCount(build) === 1 ? '' : 's' }} selected</span></div><Tag v-if="!build.enabled" value="Disabled" severity="secondary" /><Tag v-else :value="cardIssues(`builds.${index}`).length || buildInputs(build).length === 0 ? 'Needs attention' : 'Ready'" :severity="cardIssues(`builds.${index}`).length || buildInputs(build).length === 0 ? 'warn' : 'success'" /><ToggleSwitch v-model="build.enabled" :inputId="`build-${build.id}`" :aria-label="`${build.engine} enabled`" /><Button icon="pi pi-trash" text rounded severity="danger" aria-label="Remove build" @click="removeBuild(build.id)" /></div><div v-if="build.enabled" class="target-list"><button v-for="target in producerDefinition(build.engine)?.targets || []" :key="target.id" class="target-row" :class="{ selected: isTargetEnabled(build, target.id) }" :aria-pressed="isTargetEnabled(build, target.id)" @click="toggleTarget(build, target.id, !isTargetEnabled(build, target.id))"><i :class="isTargetEnabled(build, target.id) ? 'mdi mdi-check-circle' : 'mdi mdi-circle-outline'" /><span><strong>{{ target.label }}</strong><small>{{ targetDescriptorLabel(target.output || target.transform) }}</small></span></button></div><div v-if="build.enabled && buildInputs(build).length > 1" class="routing-row"><span><i class="mdi mdi-source-branch" /> Build input</span><Select :model-value="outputRefValue(build.input || { source: true })" :options="buildInputs(build)" optionLabel="label" optionValue="value" @update:model-value="setBuildInput(build, $event)" /></div><Message v-if="cardIssues(`builds.${index}`).length" severity="warn"><ul><li v-for="issue in cardIssues(`builds.${index}`)" :key="issue.code + issue.path">{{ issue.message }}</li></ul></Message></article></section>
        <div class="pipeline-divider"><span>Deploy</span></div>
        <section class="release-section"><div class="section-heading"><div><span class="eyebrow">Environments</span><h2>Deploy</h2><p>Send selected build artifacts to one or more destinations.</p></div><Select v-model="destinationToAdd" :options="availableDestinations" optionLabel="label" optionValue="id" placeholder="Add destination" @change="addDestination" /></div><div v-if="!flow.destinations.length" class="empty-card"><i class="mdi mdi-cloud-upload-outline" /><strong>No deployment jobs yet</strong><span>Add a destination to create deployment slots.</span></div><article v-for="(destination, index) in flow.destinations" :key="destination.id" class="job-card" :class="{ disabled: !destination.enabled, invalid: cardIssues(`destinations.${index}`).length }"><div class="job-header"><div class="provider-icon"><i :class="providerIcon(destinationDefinition(destination.provider)?.icon, 'mdi mdi-cloud-upload-outline')" /></div><div class="job-title"><strong>{{ destinationDefinition(destination.provider)?.label || destination.provider }}</strong><span>{{ destination.slots.length }} deployment slot{{ destination.slots.length === 1 ? '' : 's' }}</span></div><Tag v-if="!destination.enabled" value="Disabled" severity="secondary" /><Tag v-else :value="cardIssues(`destinations.${index}`).length ? 'Needs attention' : 'Ready'" :severity="cardIssues(`destinations.${index}`).length ? 'warn' : 'success'" /><ToggleSwitch v-model="destination.enabled" :inputId="`destination-${destination.id}`" aria-label="Destination enabled" /><Button icon="pi pi-trash" text rounded severity="danger" aria-label="Remove destination" @click="removeDestination(destination.id)" /></div><div v-if="destination.enabled" class="settings-grid"><ReleaseFieldControl v-for="field in destinationDefinition(destination.provider)?.fields || []" :key="field.key" :field="field" :value="fieldValue(destination.config, field.key)" :options="fieldOptions(field)" :input-id="`${destination.id}-${field.key}`" @update:value="setField(destination.config, field.key, $event)" /><div class="slot-list"><div v-for="slot in destination.slots" :key="slot.id" class="slot-row"><Select :model-value="outputRefValue(slot.input)" :options="compatibleOutputs(destination.provider)" optionLabel="label" optionValue="value" @update:model-value="setSlotInput(slot, $event)" /><ReleaseFieldControl v-for="field in destinationDefinition(destination.provider)?.slotFields || []" :key="field.key" :field="field" :value="fieldValue(slot.config, field.key)" :options="fieldOptions(field)" :input-id="`${slot.id}-${field.key}`" @update:value="setField(slot.config, field.key, $event)" /><Button icon="pi pi-trash" text rounded severity="danger" aria-label="Remove deployment slot" @click="removeSlot(destination, slot.id)" /></div><Button label="Add deployment" icon="pi pi-plus" text @click="addSlot(destination)" /></div></div><Message v-if="cardIssues(`destinations.${index}`).length" severity="warn"><ul><li v-for="issue in cardIssues(`destinations.${index}`)" :key="issue.code + issue.path">{{ issue.message }}</li></ul></Message></article></section>
      </main>
    </WorkflowShell>
    <Dialog v-model:visible="releaseDetailsVisible" modal header="Release details" :style="{ width: '560px', maxWidth: '94vw' }"><div class="settings-grid"><div class="release-field"><label for="release-version">Version</label><InputText id="release-version" v-model="releaseVersion" placeholder="1.0.0" /></div><div class="release-field wide"><label for="release-description">Description</label><Textarea id="release-description" v-model="releaseDescription" rows="3" /></div></div><template #footer><Button label="Cancel" text @click="releaseDetailsVisible = false" /><Button label="Ship release" icon="mdi mdi-rocket-launch-outline" :loading="running" :disabled="!releaseVersion.trim()" @click="runShip" /></template></Dialog>
  </Layout>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import Button from "primevue/button"; import Dialog from "primevue/dialog"; import InputText from "primevue/inputtext"; import Message from "primevue/message"; import Select from "primevue/select"; import Tag from "primevue/tag"; import Textarea from "primevue/textarea"; import ToggleSwitch from "primevue/toggleswitch";
import { matchesArtifact, resolveTargetDescriptor, type ArtifactDescriptor, type IconType, type ReleaseBuildProfileConfig, type ReleaseCatalog, type ReleaseConfig, type ReleaseDestinationConfig, type ReleaseDestinationSlot, type ReleaseFieldDefinition, type ReleaseFieldOption, type ReleaseOutputRef, type ValidationIssue } from "@pipelab/shared";
import Layout from "../components/Layout.vue"; import WorkflowShell from "../components/WorkflowShell.vue"; import ReleaseFieldControl from "../components/ReleaseFieldControl.vue"; import { useAPI } from "../composables/api";

const route = useRoute(); const router = useRouter(); const api = useAPI();
const catalog = ref<ReleaseCatalog>({ buildTypes: [], sources: [], producers: [], destinations: [] }); const flow = ref<ReleaseConfig>(); const issues = ref<ValidationIssue[]>([]); const error = ref(""); const running = ref(false); const inspectionOptions = ref<Record<string, ReleaseFieldOption[]>>({}); const buildToAdd = ref<string>(); const destinationToAdd = ref<string>(); const sourcePicker = ref<string>(); const releaseDetailsVisible = ref(false); const releaseVersion = ref("1.0.0"); const releaseDescription = ref("");
const sourceDefinition = computed(() => catalog.value.sources.find((item) => item.id === flow.value?.source.provider)); const issueCount = computed(() => issues.value.filter((issue) => issue.severity === "error").length || issues.value.length); const producerDefinition = (id: string) => catalog.value.producers.find((item) => item.id === id); const destinationDefinition = (id: string) => catalog.value.destinations.find((item) => item.id === id); const providerIcon = (icon: IconType | undefined, fallback: string) => icon?.type === "icon" ? (icon.icon.includes("mdi") || icon.icon.includes("pi-") ? icon.icon : `mdi ${icon.icon}`) : fallback;
const fieldValue = (config: Record<string, unknown>, key: string) => String(config[key] ?? ""); const setField = (config: Record<string, unknown>, key: string, value: unknown) => { config[key] = value; }; const fieldOptions = (field: ReleaseFieldDefinition) => inspectionOptions.value[field.key] || field.options || []; const cardIssues = (prefix: string) => issues.value.filter((issue) => issue.path === prefix || issue.path?.startsWith(`${prefix}.`));
const outputRefValue = (ref: ReleaseOutputRef) => "source" in ref ? "source" : `${ref.buildId}:${ref.targetId}`;
const producedArtifacts = computed(() => { const result: Array<{ value: string; label: string; ref: ReleaseOutputRef; descriptor: ArtifactDescriptor }> = []; if (sourceDefinition.value) result.push({ value: "source", label: `Source — ${sourceDefinition.value.label}`, ref: { source: true }, descriptor: sourceDefinition.value.output }); for (const build of flow.value?.builds.filter((item) => item.enabled) || []) { const input = build.input ? result.find((item) => item.value === outputRefValue(build.input!)) : result[0]; const definition = producerDefinition(build.engine); if (!definition || !input) continue; for (const target of build.targets.filter((item) => item.enabled)) { const targetDefinition = definition.targets.find((item) => item.id === target.id); const descriptor = targetDefinition && resolveTargetDescriptor(input.descriptor, targetDefinition); if (descriptor) result.push({ value: `${build.id}:${target.id}`, label: `${build.name || definition.label} — ${targetDefinition?.label || target.id}`, ref: { buildId: build.id, targetId: target.id }, descriptor }); } } return result; });
const buildInputs = (build: ReleaseBuildProfileConfig) => { const definition = producerDefinition(build.engine); return producedArtifacts.value.filter((artifact) => !("buildId" in artifact.ref && artifact.ref.buildId === build.id) && definition && matchesArtifact(artifact.descriptor, definition.accepts)).map((artifact) => ({ value: artifact.value, label: artifact.label })); }; const compatibleOutputs = (provider: string) => producedArtifacts.value.filter((artifact) => matchesArtifact(artifact.descriptor, destinationDefinition(provider)?.accepts || {})).map((artifact) => ({ value: artifact.value, label: artifact.label }));
const sourcePath = computed(() => { const field = sourceDefinition.value?.fields?.find((item) => item.type === "file" || item.type === "directory"); return field && flow.value ? fieldValue(flow.value.source.config, field.key) : ""; }); const availableProducers = computed(() => catalog.value.producers); const availableDestinations = computed(() => catalog.value.destinations.filter((item) => !flow.value?.destinations.some((destination) => destination.provider === item.id)));
const enabledTargetCount = (build: ReleaseBuildProfileConfig) => build.targets.filter((target) => target.enabled).length; const isTargetEnabled = (build: ReleaseBuildProfileConfig, id: string) => build.targets.some((target) => target.id === id && target.enabled); const targetDescriptorLabel = (descriptor?: unknown) => descriptor && typeof descriptor === "object" ? Object.values(descriptor as Record<string, unknown>).filter((value) => typeof value === "string").join(" · ") || "Output artifact" : "Output artifact";
const addBuild = () => { if (!flow.value || !buildToAdd.value) return; const definition = producerDefinition(buildToAdd.value); if (!definition) return; const first = definition.targets[0]; flow.value.builds.push({ id: `${buildToAdd.value.split("/").pop()}-${Date.now()}`, type: first?.buildType || "desktop", engine: buildToAdd.value, enabled: true, config: { ...definition.defaultConfig }, targets: definition.targets.map((target, index) => ({ id: target.id, enabled: index === 0, config: { ...target.defaultConfig } })) }); buildToAdd.value = undefined; }; const removeBuild = (id: string) => { if (flow.value) flow.value.builds = flow.value.builds.filter((build) => build.id !== id); }; const toggleTarget = (build: ReleaseBuildProfileConfig, id: string, enabled: boolean) => { const target = build.targets.find((item) => item.id === id); if (target) target.enabled = enabled; else { const definition = producerDefinition(build.engine)?.targets.find((item) => item.id === id); if (definition) build.targets.push({ id, enabled, config: { ...definition.defaultConfig } }); } }; const setBuildInput = (build: ReleaseBuildProfileConfig, value: string) => { const artifact = producedArtifacts.value.find((item) => item.value === value); if (artifact) build.input = artifact.ref; };
const addDestination = () => { if (!flow.value || !destinationToAdd.value) return; const definition = destinationDefinition(destinationToAdd.value); if (definition) flow.value.destinations.push({ id: `${destinationToAdd.value.split("/").pop()}-${Date.now()}`, provider: destinationToAdd.value, enabled: true, config: { ...definition.defaultConfig }, slots: [] }); destinationToAdd.value = undefined; }; const removeDestination = (id: string) => { if (flow.value) flow.value.destinations = flow.value.destinations.filter((item) => item.id !== id); }; const addSlot = (destination: ReleaseDestinationConfig) => { const artifact = compatibleOutputs(destination.provider)[0]; if (artifact) destination.slots.push({ id: `${destination.id}-${destination.slots.length + 1}`, enabled: true, input: producedArtifacts.value.find((item) => item.value === artifact.value)!.ref, config: {} }); }; const removeSlot = (destination: ReleaseDestinationConfig, id: string) => { destination.slots = destination.slots.filter((slot) => slot.id !== id); }; const setSlotInput = (slot: ReleaseDestinationSlot, value: string) => { const artifact = producedArtifacts.value.find((item) => item.value === value); if (artifact) slot.input = artifact.ref; };
const changeSource = () => { if (!flow.value || !sourcePicker.value) return; const definition = catalog.value.sources.find((item) => item.id === sourcePicker.value); if (definition) flow.value.source = { provider: definition.id, config: { ...definition.defaultConfig } }; void inspectSource(); }; const inspectResult = (result: { issues?: ValidationIssue[]; fieldOptions?: Record<string, ReleaseFieldOption[]> }) => { issues.value = result.issues || []; for (const [key, options] of Object.entries(result.fieldOptions || {})) if (options.length) inspectionOptions.value[key] = options; }; const inspectSource = async () => { if (!flow.value) return; const result = await api.execute("release:source:inspect", { provider: flow.value.source.provider, config: flow.value.source.config }); if (result.type === "success") inspectResult(result.result as { issues?: ValidationIssue[]; fieldOptions?: Record<string, ReleaseFieldOption[]> }); };
const validate = async () => { if (!flow.value) return false; const result = await api.execute("release:validate", { config: flow.value }); if (result.type === "error") { error.value = result.ipcError; return false; } issues.value = result.result.issues; return !issues.value.some((issue) => issue.severity === "error"); }; const save = async () => { if (!flow.value) return; const result = await api.execute("workflow:save-by-name", { name: `workflows/${route.params.flowId}`, data: JSON.stringify(flow.value) }); if (result.type === "error") error.value = result.ipcError; }; const ship = async () => { if (await validate()) { releaseVersion.value = "1.0.0"; releaseDescription.value = flow.value?.description || flow.value?.name || ""; releaseDetailsVisible.value = true; } }; const runShip = async () => { if (!flow.value) return; releaseDetailsVisible.value = false; running.value = true; await save(); const result = await api.execute("workflow:execute", { name: `workflows/${route.params.flowId}`, release: { version: releaseVersion.value.trim(), description: releaseDescription.value.trim() } }, async (event) => { if (event.type === "workflow-run") await router.push(`/workflows/${route.params.flowId}/${route.params.projectId}/runs/${event.data.runId}`); }); if (result.type === "error") error.value = result.ipcError; running.value = false; };
let saveTimer: ReturnType<typeof setTimeout> | undefined; watch(flow, () => { clearTimeout(saveTimer); if (flow.value) saveTimer = setTimeout(save, 700); }, { deep: true }); onMounted(async () => { const [catalogResult, flowResult] = await Promise.all([api.execute("release:catalog:get"), api.execute("workflow:load-by-name", { name: `workflows/${route.params.flowId}` })]); if (catalogResult.type === "success") catalog.value = catalogResult.result; if (flowResult.type === "success") { flow.value = flowResult.result as ReleaseConfig; sourcePicker.value = flow.value.source.provider; await inspectSource(); } else error.value = flowResult.ipcError; });
</script>

<style scoped>
.release-page { max-width: 1040px; margin: 0 auto; padding-bottom: 48px; }.autosave-state { color: var(--p-text-muted-color, var(--text-color-secondary)); font-size: .75rem; }.autosave-state i { color: var(--green-500, #22c55e); margin-right: 4px; }.summary-copy { display: block; margin-top: 4px; font-size: .8rem; }.release-section { display: grid; gap: 12px; }.section-heading { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin: 22px 2px 4px; }.section-heading h2 { margin: 3px 0 0; font-size: 1.15rem; }.section-heading p { margin: 4px 0 0; color: var(--p-text-muted-color, var(--text-color-secondary)); font-size: .8rem; }.eyebrow { color: var(--p-text-muted-color, var(--text-color-secondary)); font-size: .68rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }.source-card, .job-card, .empty-card { border: 1px solid var(--p-surface-200, var(--surface-border)); border-radius: 10px; background: var(--p-surface-0, var(--surface-card)); }.source-card, .job-header { display: flex; align-items: center; gap: 12px; }.source-card { padding: 12px 14px; }.source-copy, .job-title { display: grid; gap: 3px; min-width: 0; flex: 1; }.source-copy strong, .job-title strong { font-size: .9rem; }.source-copy span, .job-title span { overflow: hidden; color: var(--p-text-muted-color, var(--text-color-secondary)); font-size: .75rem; text-overflow: ellipsis; white-space: nowrap; }.provider-icon { display: grid; place-items: center; width: 36px; height: 36px; flex: 0 0 auto; border: 1px solid var(--p-surface-200, var(--surface-border)); border-radius: 8px; color: var(--primary-color); background: var(--p-surface-50, var(--surface-ground)); font-size: 18px; }.job-card { overflow: hidden; }.job-header { padding: 12px 14px; }.target-list, .settings-grid, .slot-list { display: grid; gap: 8px; padding: 0 14px 14px; }.target-row, .slot-row { display: flex; align-items: center; gap: 10px; border: 1px solid var(--p-surface-200, var(--surface-border)); border-radius: 7px; padding: 9px 10px; background: transparent; color: var(--text-color); text-align: left; }.target-row { cursor: pointer; }.target-row.selected { border-color: var(--primary-color); background: color-mix(in srgb, var(--primary-color) 7%, transparent); }.target-row span { display: grid; gap: 2px; flex: 1; }.target-row small { color: var(--p-text-muted-color, var(--text-color-secondary)); font-size: .7rem; }.routing-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 0 14px 14px; font-size: .78rem; }.slot-row > :first-child { flex: 1; }.empty-card { display: grid; place-items: center; gap: 6px; padding: 30px; color: var(--p-text-muted-color, var(--text-color-secondary)); text-align: center; }.empty-card i { color: var(--primary-color); font-size: 25px; }.pipeline-divider { display: flex; align-items: center; gap: 12px; margin: 28px 0 -8px; color: var(--p-text-muted-color, var(--text-color-secondary)); font-size: .68rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }.pipeline-divider::after { height: 1px; flex: 1; background: var(--surface-border); content: ""; }.release-field { display: grid; gap: 5px; }.wide { grid-column: 1 / -1; }
</style>
